                    a = routes[i]
                    b = routes[j]
                    cand1 = a + b
                    cand2 = b + a
                    if route_cost(cand2) < route_cost(cand1):
                        merged = cand2
                    else:
                        merged = cand1
                    routes[i] = merged
                    del routes[j]
                    changed = True
                    break
                j += 1
            if changed:
                break
            i += 1

    # ---- local search: intra-route 2-opt ----
    def two_opt_route(r):
        n = len(r)
        if n < 4:
            return r, False
        best = r
        best_cost = route_cost(r)
        improved = False
        for i in range(n - 2):
            for k in range(i + 2, n):
                cand = r[:i + 1] + r[i + 1:k + 1][::-1] + r[k + 1:]
                c = route_cost(cand)
                if c + 1e-12 < best_cost:
                    best = cand
                    best_cost = c
                    improved = True
        return best, improved

    improved = True
    while improved:
        improved = False
        for idx in range(len(routes)):
            newr, ok = two_opt_route(routes[idx])
            if ok:
                routes[idx] = newr
                improved = True

    # ---- local search: relocate customer between routes ----
    improved = True
    while improved:
        improved = False
        best_delta = 0.0
        best_move = None
        for i in range(len(routes)):
            for pi in range(len(routes[i])):
                cid = routes[i][pi]
                dem = demand[cid]
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if route_demand(routes[j]) + dem > capacity:
                        continue
                    base_i = routes[i]
                    base_j = routes[j]
                    # remove cid from i
                    ri = base_i[:pi] + base_i[pi + 1:]
                    # try all insertion positions in j
                    for pj in range(len(base_j) + 1):
                        rj = base_j[:pj] + [cid] + base_j[pj:]
                        old_cost = route_cost(base_i) + route_cost(base_j)
                        new_cost = route_cost(ri) + route_cost(rj)
                        delta = old_cost - new_cost
                        if delta > best_delta + 1e-12:
                            best_delta = delta
                            best_move = (i, j, pi, pj, ri, rj)
        if best_move is not None:
            i, j, pi, pj, ri, rj = best_move
            routes[i] = ri
            routes[j] = rj
            # remove empties
            routes = [r for r in routes if r]
            improved = True
            # quick cleanup 2-opt on affected routes
            for idx in range(len(routes)):
                newr, ok = two_opt_route(routes[idx])
                if ok:
                    routes[idx] = newr

    # ---- final cleanup: ensure all customers appear once ----
    seen = {}
    for r in routes:
        for cid in r:
            seen[cid] = seen.get(cid, 0) + 1

    missing = [cid for cid in customers if seen.get(cid, 0) == 0]
    extra = [cid for cid, cnt in seen.items() if cnt > 1]

    # Remove duplicates deterministically
    if extra:
        for cid in extra:
            cnt = seen[cid]
            while cnt > 1:
                removed = False
                for r in routes:
                    if cid in r:
                        r.remove(cid)
                        cnt -= 1
                        removed = True
                        break
                if not removed:
                    break
        routes = [r for r in routes if r]

    # Insert missing customers using best feasible position
    for cid in missing:
        dem = demand[cid]
        best = None
        best_inc = None
        for i in range(len(routes)):
            if route_demand(routes[i]) + dem > capacity:
                continue
            r = routes[i]
            for p in range(len(r) + 1):
                cand = r[:p] + [cid] + r[p:]
                inc = route_cost(cand) - route_cost(r)
                if best is None or inc < best_inc - 1e-12 or (abs(inc - best_inc) <= 1e-12 and (i, p) < (best[0], best[1])):
                    best = (i, p, cand)
                    best_inc = inc
        if best is None:
            routes.append([cid])
        else:
            i, p, cand = best
            routes[i] = cand

    # Final deterministic ordering of routes by first customer id
    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (r[0], len(r), r))

    return routes
